{
  "title": "Обговорення життя і роботи за кордоном у Словакії та Австрії",
  "topics": [
    {
      "id": "abroad-residence",
      "title": "Хто живе за кордоном",
      "claims": [
        {
          "text": "У групі є учасники, які живуть у Братиславі (Словакія) і в Австрії.",
          "evidence": [1, 4, 43]
        },
        {
          "text": "Деякі учасники планують переїхати до інших країн (Варшава, Ірландія, Норвегія, Іспанія).",
          "evidence": [59, 60]
        }
      ]
    },
    {
      "id": "job-search",
      "title": "Пошук роботи за кордоном",
      "claims": [
        {
          "text": "Для пошуку роботи за кордоном рекомендовано використовувати LinkedIn.",
          "evidence": [18]
        },
        {
          "text": "Автор (P3) надіслав близько 100 вакансій і отримав лише 3 інтерв'ю.",
          "evidence": [21]
        },
        {
          "text": "Більшість вакансій вимагає знання місцевої мови (наприклад, B2 або B1).",
          "evidence": [46, 26]
        },
        {
          "text": "Високий рівень освіти рідко впливає на прийом на роботу.",
          "evidence": [32]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Вимоги до мови",
      "claims": [
        {
          "text": "У Австрії основною мовою спілкування є німецька, проте в робочому середовищі часто використовують англійську.",
          "evidence": [14, 15, 55]
        },
        {
          "text": "Для багатьох позицій потрібен рівень німецької B2, іноді достатній B1 без сертифікату.",
          "evidence": [46]
        },
        {
          "text": "Автор (P3) вивчає німецьку, бо відчуває дискомфорт у повсякденному спілкуванні.",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "salary-expectations",
      "title": "Заробітна плата",
      "claims": [
        {
          "text": "Зарплати в Європі зазвичай вищі, ніж в Україні, хоча часто не звертають на це увагу.",
          "evidence": [35]
        },
        {
          "text": "Автор (P3) отримав мінімальну зарплату, хоча могла бути вища, бо був готовий прийняти будь-яку пропозицію.",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "integration-experiences",
      "title": "Адаптація та соціальна інтеграція",
      "claims": [
        {
          "text": "У повсякденному житті мовний бар’єр створює незручності та знижує впевненість.",
          "evidence": [51, 52, 53]
        },
        {
          "text": "У професійному середовищі англійська достатня для технічних пояснень.",
          "evidence": [55]
        },
        {
          "text": "Автор (P3) планує поїхати на технічний івент у Варшаву.",
          "evidence": [59]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Чи планує учасник (P3) залишитися в Австрії або переїхати в іншу країну?",
      "evidence": [58, 60]
    }
  ]
}
